package securitytests

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"

	sdkcrypto "github.com/cosmos/cosmos-sdk/crypto"
	"github.com/cosmos/cosmos-sdk/crypto/keys/secp256k1"
)

func TestCanonicalSDKArmorFixtures(t *testing.T) {
	// Fixtures contain only an artificial unfunded key. They were generated by
	// canonical SDK v0.53.8 before installing the declared source patch.
	data, err := os.ReadFile("testdata/sdk-armor-v0538.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixtures []string
	if err := json.Unmarshal(data, &fixtures); err != nil {
		t.Fatal(err)
	}
	if len(fixtures) != 3 {
		t.Fatal("incomplete canonical fixtures")
	}
	info, err := sdkcrypto.UnarmorInfoBytes(fixtures[0])
	if err != nil || string(info) != "ordinary SDK information" {
		t.Fatalf("legacy info: %v", err)
	}
	key := secp256k1.GenPrivKeyFromSecret([]byte("synthetic unfunded armor fixture"))
	public, algorithm, err := sdkcrypto.UnarmorPubKeyBytes(fixtures[1])
	if err != nil || algorithm != "secp256k1" || !bytes.Equal(public, key.PubKey().Bytes()) {
		t.Fatalf("legacy public key: %v", err)
	}
	private, algorithm, err := sdkcrypto.UnarmorDecryptPrivKey(fixtures[2], "synthetic test password")
	if err != nil || algorithm != "secp256k1" || !bytes.Equal(private.Bytes(), key.Bytes()) {
		t.Fatalf("legacy encrypted synthetic key: %v", err)
	}
	if _, _, err := sdkcrypto.UnarmorDecryptPrivKey(fixtures[2], "incorrect password"); err == nil {
		t.Fatal("wrong password accepted")
	}
	wrapped := sdkcrypto.EncryptArmorPrivKey(key, "synthetic new password", "secp256k1")
	private, _, err = sdkcrypto.UnarmorDecryptPrivKey(wrapped, "synthetic new password")
	if err != nil || !bytes.Equal(private.Bytes(), key.Bytes()) {
		t.Fatalf("new encrypted synthetic key: %v", err)
	}
}
